import {createBust} from './busts.js';
import {CATALOG} from './catalog.js';
import {registerCatalogBusts} from './catalog-busts.js';
registerCatalogBusts(CATALOG);
export function speechPose(time,playing,energy=0){const phase=((time%4.7)+4.7)%4.7;return {jaw:playing?Math.min(1,energy):0,blink:phase>4.48?Math.max(.05,Math.abs(phase-4.59)/.11):1,yaw:Math.sin(time*.55)*.075,nod:Math.sin(time*.83)*.025};}
const meters=new WeakMap();let context;
function meterFor(audio){if(!audio)return null;if(meters.has(audio))return meters.get(audio);try{context ||= new (window.AudioContext||window.webkitAudioContext)();const source=context.createMediaElementSource(audio),analyser=context.createAnalyser();analyser.fftSize=256;source.connect(analyser);analyser.connect(context.destination);const meter={analyser,data:new Uint8Array(analyser.fftSize)};meters.set(audio,meter);return meter;}catch{return null;}}
export class TalkingBustView{
 constructor(host,{id='lula',audio=()=>null}={}){this.host=host;this.id=id;this.audio=audio;this.playing=false;this.start=performance.now();this.destroyed=false;host.classList.add('talking-stage');host.setAttribute('role','img');host.setAttribute('aria-label','Personagem educativo estilizado de Lula, com cabeça, olhos e boca animados');this.fallback();this.build3D();this.resize=new ResizeObserver(()=>{if(this.renderer){const w=host.clientWidth,h=host.clientHeight;this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();}});this.resize.observe(host);this.frame=this.frame.bind(this);this.raf=requestAnimationFrame(this.frame);}
 fallback(){this.host.innerHTML=`<svg viewBox="0 0 420 470" aria-hidden="true"><defs><radialGradient id="skin"><stop stop-color="#dfb391"/><stop offset="1" stop-color="#b58165"/></radialGradient><linearGradient id="suit"><stop stop-color="#183e36"/><stop offset="1" stop-color="#0d2624"/></linearGradient></defs><ellipse cx="210" cy="422" rx="123" ry="17" fill="#142d27" opacity=".18"/><path d="M155 380H265L275 433H145Z" fill="#c6b58f"/><path d="M101 382V319Q114 286 177 281H243Q302 286 319 319V382Z" fill="url(#suit)"/><path d="M178 285L210 354L244 285" fill="#f6f0e0"/><path d="M203 298H217L227 350L210 365L194 350Z" fill="#8a4240"/><g class="avatar-head"><rect x="183" y="235" width="54" height="65" rx="23" fill="#bc896b"/><ellipse cx="139" cy="182" rx="18" ry="30" fill="#bd8a6e"/><ellipse cx="281" cy="182" rx="18" ry="30" fill="#bd8a6e"/><ellipse cx="210" cy="170" rx="75" ry="108" fill="url(#skin)"/><path d="M137 173Q113 78 171 65Q208 44 251 70Q298 91 283 172L269 126Q249 84 209 87Q164 85 150 128Z" fill="#d6d4ca"/><path d="M146 204Q155 256 181 278Q210 301 242 275Q271 245 275 201Q255 219 241 222Q210 213 181 222Z" fill="#e3dfd3"/><path d="M175 216Q193 195 210 209Q227 195 246 216L236 226Q211 216 185 226Z" fill="#eeeadf"/><path d="M207 158L198 196Q211 204 222 195" fill="none" stroke="#aa7258" stroke-width="7" stroke-linecap="round"/><g class="avatar-eyes"><ellipse cx="177" cy="161" rx="15" ry="8" fill="#f6f2e7"/><ellipse cx="244" cy="161" rx="15" ry="8" fill="#f6f2e7"/><circle cx="179" cy="161" r="5" fill="#43362c"/><circle cx="242" cy="161" r="5" fill="#43362c"/></g><path d="M160 143Q176 134 191 142M230 142Q245 134 260 144" fill="none" stroke="#b6b1a5" stroke-width="7" stroke-linecap="round"/><ellipse class="avatar-mouth" cx="210" cy="235" rx="22" ry="3" fill="#583d35"/><path d="M187 232Q210 237 233 232" fill="none" stroke="#a87b69" stroke-width="3"/></g><text x="210" y="414" fill="#3b4f40" text-anchor="middle" font-family="Georgia" font-size="17">LULA · ESTUDO EDUCATIVO</text></svg>`;this.head=this.host.querySelector('.avatar-head');this.eyes=this.host.querySelector('.avatar-eyes');this.mouth=this.host.querySelector('.avatar-mouth');this.host.dataset.renderer='illustration';}
 build3D(){const T=window.AFRAME?.THREE;if(!T)return;let renderer;try{const canvas=document.createElement('canvas');if(!canvas.getContext('webgl2'))return;renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.scene=new T.Scene();this.camera=new T.PerspectiveCamera(34,1,.1,30);this.camera.position.set(0,1,3.6);this.camera.lookAt(0,.75,0);this.scene.add(new T.HemisphereLight('#fff4db','#325248',3));const light=new T.DirectionalLight('#fff0de',3);light.position.set(-2,4,4);this.scene.add(light);this.bust=createBust(T,this.id);this.pivot=new T.Group();this.pivot.position.y=.65;for(const child of [...this.bust.children]){if(/Cabeça|Orelha|orelha|Olho|ocular|Pálpebra|Sobrancelha|nariz|boca|Lábio|Queixo|Cabelo|Mecha|Barba|barba|Bigode/.test(child.name)){this.bust.remove(child);child.position.y-=.65;this.pivot.add(child);}}this.bust.add(this.pivot);this.bust.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.material.metalness=.05;o.material.roughness=.8;if(/Cabelo|Mecha|Barba|barba|Bigode/.test(o.name))o.material.color.set('#d9d5ca');else if(/ombros|Lapela|Costura/.test(o.name))o.material.color.set('#173b34');else if(/Gravata|Nó/.test(o.name))o.material.color.set('#823f39');else o.material.color.set('#cc9b7c');}});this.jaw=new T.Mesh(new T.SphereGeometry(1,24,16),new T.MeshStandardMaterial({color:'#583b34',roughness:1}));this.jaw.position.set(0,.25,.335);this.jaw.scale.set(.072,.006,.012);this.pivot.add(this.jaw);this.eyeMeshes=[];for(const sign of [-1,1]){const eye=new T.Mesh(new T.SphereGeometry(1,20,12),new T.MeshStandardMaterial({color:'#4b3f32'}));eye.position.set(sign*.103,.435,.25);eye.scale.set(.021,.013,.009);this.pivot.add(eye);this.eyeMeshes.push(eye);}this.scene.add(this.bust);const base=new T.Mesh(new T.CylinderGeometry(.48,.54,.22,48),new T.MeshStandardMaterial({color:'#c3b38d',roughness:.85}));base.position.y=-.1;this.scene.add(base);this.renderer=renderer;this.host.append(renderer.domElement);this.host.querySelector('svg').style.display='none';this.host.dataset.renderer='webgl';}catch{renderer?.dispose();}}
 setState(state){this.playing=state==='playing';if(this.playing){this.meter=meterFor(this.audio());context?.resume().catch(()=>{});}}
 frame(now){if(this.destroyed)return;const time=(now-this.start)/1000;let energy=0;if(this.playing&&this.meter){const {analyser,data}=this.meter;analyser.getByteTimeDomainData(data);energy=Math.min(1,Math.sqrt(data.reduce((s,v)=>s+((v-128)/128)**2,0)/data.length)*8);}else if(this.playing)energy=.25+.25*Math.abs(Math.sin(time*10));const p=speechPose(time,this.playing,energy);if(this.renderer){this.pivot.rotation.set(p.nod,p.yaw,0);this.jaw.scale.y=.006+p.jaw*.038;for(const eye of this.eyeMeshes)eye.scale.y=.013*p.blink;this.renderer.render(this.scene,this.camera);}else{this.head.style.transform=`rotate(${p.yaw*30}deg) translateY(${p.nod*35}px)`;this.head.style.transformOrigin='210px 280px';this.eyes.style.transform=`translateY(${161*(1-p.blink)}px) scaleY(${p.blink})`;this.mouth.setAttribute('ry',String(3+p.jaw*13));}this.raf=requestAnimationFrame(this.frame);}
 destroy(){this.destroyed=true;cancelAnimationFrame(this.raf);this.resize.disconnect();if(this.scene)this.scene.traverse(o=>{o.geometry?.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose());});this.renderer?.dispose();this.host.replaceChildren();}
}
